// src/app/star-rating.component.ts
import { ChangeDetectionStrategy, Component, computed, input, model } from '@angular/core';

@Component({
  selector: 'app-star-rating',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './star-rating.component.html',
  styleUrls: ['./star-rating.component.css']
})
export class StarRatingComponent {
  readonly max = input(5);
  readonly rating = model(0);
  readonly stars = computed(() => Array.from({ length: this.max() }, (_, i) => i + 1));

  onRate(value: number): void {
    if (value < 1 || value > this.max()) {
      return;
    }
    // Setting a model also emits ratingChange, the event [(rating)] in the parent listens to.
    this.rating.set(value);
  }
}

// src/app/app.component.ts
import { ChangeDetectionStrategy, Component, signal } from '@angular/core';
import { StarRatingComponent } from './star-rating.component';

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [StarRatingComponent],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly currentRating = signal(0);
}
